// === Tab: mySketch ===
let x;
let y;
let a, b, c, d;
let num_points = 1000

function setup() {
	//equations
	//xt+1 = sin(a * yt) - cos(b * xt)
	//yt+1 = sin(c * xt) - cos(d * yt)
	createCanvas(windowWidth, screen.availHeight);
	// createCanvas(windowWidth*2, windowHeight*2);
	colorMode(HSB, 100);
	// background(100);
	stroke(50);
	x = 0;
	y = 0;

	// a = 2.01;
	// b = -0.49;
	// c = 1.24;
	// d = 1.88;
	a = random(-3,3);
	b = random(-3,3);
	c = random(-3,3);
	d = random(-3,3);
	// a = 2;
	// b=-7;
	// c=-1.2;
	// d=2;
	// console.log(a);
	// console.log(b);
	// console.log(c);
	// console.log(d);
}

function draw() {
	// // noLoop()
	blendMode(MULTIPLY);

	background(100);

	noFill()
	// beginShape(POINTS)
	for(let i=0; i<num_points; i++){

		x_plot = map(x, -2,2, 0, width, true);
		y_plot = map(y, -2,2, 0, height, true);

		point(x_plot,y_plot);
		// vertex(x_plot, y_plot);

		x2 = sin(a * y) - cos(b * x)
		y2 = sin(c * x) - cos(d * y)	
		stroke(map(x2, -2, 2, 40, 100), map(y2, -2, 2, 10, 60), 100);
		// stroke(50);

		x = x2;
		y = y2;
	}
	// endShape()
	// da = 0.005
	// db = 0.001
	// dc = 0.005
	// // a -= da
	// b -= db
	// c -= dc
	// if (a < -3 || a > 3){da*=-1}
	// if (b < -3 || b > 3){db*=-1}
	// if (c < -3 || c > 3){dc*=-1}
}

function mousePressed() {
	blendMode(BLEND);
	background(100);
	num_points = 25000;
	a = random(-3,3);
	b = random(-3,3);
	c = random(-3,3);
	d = random(-3,3);
  draw()
}

function keyPressed() {
	if (key == 's') {
		saveCanvas('de_jong_attractor', 'png');
	} else{
		num_points = 250000;
		draw()
	}
}

function deviceShaken() {
	num_points = 250000;
	draw()
}

function keyPressed(){
	save('pix.jpg');
}

